/**
 * General utility functions
 *
 * @author Andreas Schwarte
 * @since 5.0
 */
public class FedXUtil {

	private static final Logger log = LoggerFactory.getLogger(FedXUtil.class);

	private static final AtomicLong count = new AtomicLong(0L);

	/**
	 * @param iri
	 * @return the IRI for the full URI string
	 */
	public static IRI iri(String iri) {
		return valueFactory().createIRI(iri);
	}

	/**
	 *
	 * @param literal
	 * @return the string literal
	 */
	public static Literal literal(String literal) {
		return valueFactory().createLiteral(literal);
	}

	/**
	 *
	 * @return a {@link SimpleValueFactory} instance
	 */
	public static ValueFactory valueFactory() {
		return SimpleValueFactory.getInstance();
	}

	/**
	 * Apply query bindings to transfer information from the query into the evaluation routine, e.g. the query execution
	 * time.
	 *
	 * @param query
	 */
	public static void applyQueryBindings(SailQuery query) {
		query.setBinding(FedXRepositoryConnection.BINDING_ORIGINAL_MAX_EXECUTION_TIME,
				FedXUtil.valueFactory().createLiteral(query.getMaxExecutionTime()));
	}

	/**
	 * Hexadecimal representation of an incremental integer.
	 *
	 * @return an incremental hex UUID
	 */
	public static String getIncrementalUUID() {
		long id = count.incrementAndGet();
		return Long.toHexString(id);
	}

	/**
	 * Set a maximum execution time corresponding to {@link FedXConfig#getEnforceMaxQueryTime()} to this operation.
	 *
	 * Note that this is an upper bound only as FedX applies other means for evaluation the maximum query execution
	 * time.
	 *
	 * @param operation         the {@link Operation}
	 * @param federationContext the {@link FederationContext}
	 */
	public static void applyMaxQueryExecutionTime(Operation operation, FederationContext federationContext) {
		int maxExecutionTime = federationContext.getConfig().getEnforceMaxQueryTime();
		if (maxExecutionTime <= 0) {
			return;
		}
		operation.setMaxExecutionTime(maxExecutionTime);
	}

	/**
	 * Convert the given contexts to a {@link Dataset} representation.
	 *
	 * @param contexts
	 * @return
	 */
	public static Dataset toDataset(Resource[] contexts) {
		SimpleDataset dataset = new SimpleDataset();
		for (Resource context : contexts) {
			if (context != null && !(context instanceof IRI)) {
				throw new QueryEvaluationException(
						"Unsupported blank-node identity: SPARQL Protocol datasets require IRI graph sources");
			}
			dataset.addDefaultGraph((IRI) context);
		}
		return dataset;
	}

	/**
	 * Convert the given {@link Dataset} to an array of contexts
	 *
	 * @param ds
	 * @return
	 */
	public static Resource[] toContexts(Dataset ds) {
		ds = toRdfDataset(ds);
		if (ds == null) {
			return new Resource[0];
		}
		return ds.getDefaultGraphResources().stream().map(FedXUtil::physicalContext).toArray(Resource[]::new);
	}

	/**
	 * Whether a statement's selected graph is present in the query dataset. Endpoint-only wrappers leave the RDF
	 * dataset implicit.
	 */
	public static boolean isContextAvailable(StatementPattern statement, Dataset dataset) {
		if (statement instanceof GraphSelectionAware aware && aware.getResolvedGraphSelection() != null) {
			// GRAPH has already checked membership; its physical selection is independent of default graph sets.
			return true;
		}
		dataset = toRdfDataset(dataset);
		if (!hasGraphSelection(dataset)) {
			return true;
		}
		if (statement.getScope() == Scope.NAMED_CONTEXTS) {
			return !dataset.getNamedGraphResources().isEmpty() && (statement.getContextVar() == null
					|| !statement.getContextVar().hasValue()
					|| dataset.getNamedGraphResources().contains(statement.getContextVar().getValue()));
		}
		return !dataset.getDefaultGraphResources().isEmpty();
	}

	/** Retrieve the physical contexts selected by the statement and dataset. */
	public static Resource[] toContexts(StatementPattern stmt, Dataset dataset) {
		if (stmt instanceof GraphSelectionAware aware && aware.getResolvedGraphSelection() != null) {
			return new Resource[] { aware.getResolvedGraphSelection().physicalGraph() };
		}
		dataset = toRdfDataset(dataset);
		if (stmt.getScope() == Scope.NAMED_CONTEXTS) {
			if (stmt.getContextVar() != null && stmt.getContextVar().hasValue()) {
				Resource graph = (Resource) stmt.getContextVar().getValue();
				return new Resource[] { dataset != null && dataset.getNamedGraphResources().contains(graph)
						? graph
						: physicalContext(graph) };
			}
			return !hasGraphSelection(dataset) ? new Resource[0]
					: dataset.getNamedGraphResources().stream().map(FedXUtil::physicalContext).toArray(Resource[]::new);
		}
		return toContexts(dataset);
	}

	/**
	 * Removes federation-only endpoint selection wrappers before a dataset is passed to a repository query. When a
	 * parser fallback combines an external dataset with a query-level dataset, rebuild it through the same fallback
	 * factory so its primary-versus-fallback graph-set semantics remain intact.
	 */
	public static Dataset toRdfDataset(Dataset dataset) {
		if (dataset instanceof FedXDataset fedx) {
			return toRdfDataset(fedx.getDelegate());
		}
		if (dataset instanceof FallbackDataset fallback) {
			Dataset primary = toRdfDataset(fallback.getPrimary());
			Dataset secondary = toRdfDataset(fallback.getFallback());
			return FallbackDataset.fallback(primary, secondary);
		}
		return dataset;
	}

	/**
	 * Whether the effective RDF dataset selects read graphs, including an explicitly empty read selection. Retain the
	 * dataset itself so INSERT/DELETE metadata and fallback precedence remain intact.
	 */
	public static boolean hasDatasetGraphSelection(Dataset dataset) {
		return hasGraphSelection(toRdfDataset(dataset));
	}

	private static boolean hasGraphSelection(Dataset dataset) {
		return dataset != null && (dataset.isExplicitReadDataset() || !dataset.getDefaultGraphResources().isEmpty()
				|| !dataset.getNamedGraphResources().isEmpty());
	}

	private static Resource physicalContext(Resource graph) {
		return RDF4J.NIL.equals(graph) || SESAME.NIL.equals(graph) ? null : graph;
	}

	/**
	 * Returns a {@link Dataset} representation of the given {@link StatementPattern} and {@link Dataset}.
	 * <p>
	 * If the {@link StatementPattern} does not have a context value, the {@link Dataset} is returned as-is, which may
	 * also be <code>null</code>.
	 * </p>
	 *
	 * <p>
	 * Otherwise the newly constructed {@link Dataset} contains all information from the original one plus the context
	 * from the statement.
	 * </p>
	 *
	 * @param stmt
	 * @param dataset
	 * @return
	 */
	public static Dataset toDataset(StatementPattern stmt, Dataset dataset) {
		if (stmt.getContextVar() == null || !stmt.getContextVar().hasValue()) {
			return dataset;
		}
		SimpleDataset res = new SimpleDataset();
		if (dataset != null) {
			res.setExplicitReadDataset(dataset.isExplicitReadDataset());
			dataset.getDefaultGraphResources().forEach(iri -> res.addDefaultGraph(iri));
			dataset.getNamedGraphResources().forEach(iri -> res.addNamedGraph(iri));
			dataset.getDefaultRemoveGraphResources().forEach(iri -> res.addDefaultRemoveGraph(iri));
			res.setDefaultInsertGraph(dataset.getDefaultInsertGraphResource());
		}
		Value stmtContext = stmt.getContextVar().getValue();
		if (stmtContext instanceof IRI) {
			res.addDefaultGraph((IRI) stmtContext);
		} else {
			throw new QueryEvaluationException(
					"Unsupported blank-node identity: SPARQL Protocol graph sources require IRIs");
		}
		return res;
	}
}
